mapper.select:
SELECT 
FROM dms_commission_record
WHERE id = #{id} AND tenant_id = #{tenantId}

SELECT 
FROM dms_commission_record

    tenant_id = #{tenantId}
    AND agent_id = #{query.agentId}
    AND order_no LIKE CONCAT('%', #{query.orderNo}, '%')
    AND status = #{query.status}
    AND commission_level = #{query.commissionLevel}
    AND bonus_type = #{query.bonusType}
    AND create_time >= #{query.startTime}
    AND create_time <= #{query.endTime}

ORDER BY create_time DESC, id DESC

SELECT 
FROM dms_commission_record
WHERE record_no = #{recordNo} AND tenant_id = #{tenantId}

SELECT 
FROM dms_commission_record WHERE tenant_id = #{tenantId}
ORDER BY create_time DESC

SELECT 
FROM dms_commission_record r
WHERE r.status = 0 AND r.tenant_id = #{tenantId}
  AND create_time <= #{cutoffTime}
  AND create_time >= #{periodStart}
  AND create_time <= #{periodEnd}
  AND NOT EXISTS (
      SELECT 1 FROM dms_commission_settlement_item item
      INNER JOIN dms_commission_settlement_batch batch ON batch.id = item.batch_id
      WHERE item.commission_record_id = r.id
        AND item.tenant_id = #{tenantId}
        AND batch.tenant_id = #{tenantId}
        AND batch.status = 0
  )
ORDER BY r.id

SELECT r.*
FROM dms_commission_record r
INNER JOIN (
    SELECT id, tenant_id, status, receive_time FROM dms_shop_order
) o ON o.id = r.order_id
WHERE r.status = 0
  AND r.tenant_id = #{tenantId}
  AND o.tenant_id = #{tenantId}
  AND r.commission_amount > 0
  AND o.status = 3
  AND o.receive_time IS NOT NULL
  AND o.receive_time <= #{receivedCutoff}
  AND NOT EXISTS (
      SELECT 1 FROM dms_shop_after_sale a
      WHERE a.order_id = r.order_id AND a.status IN (0, 4, 5, 6)
  )
ORDER BY o.receive_time, r.id
LIMIT #{limit}

SELECT IFNULL(SUM(commission_amount), 0)
FROM dms_commission_record
WHERE agent_id = #{agentId} AND status = 0 AND tenant_id = #{tenantId}

SELECT IFNULL(SUM(commission_amount), 0)
FROM dms_commission_record
WHERE agent_id = #{agentId} AND status = 1 AND tenant_id = #{tenantId}

