SET status = #{record.status},
    settle_time = #{record.settleTime},
    cancel_reason = #{record.cancelReason},
    remark = #{record.remark}
WHERE id = #{record.id} AND tenant_id = #{tenantId}

UPDATE dms_commission_record
SET status = #{status}
WHERE id = #{id} AND tenant_id = #{tenantId}

